// Single Tier-2 CodeMode Script Orchestrating Across All 6 Layers
export async function run(args: any, ctx: AvosRuntimeContext) {
  // ── LAYER 1 & 2: Virtual CLI in V8 Isolate (Sub-5ms) ──────────────────────
  // Branch git repository and patch frontend configuration
  await ctx.cli.exec("git checkout -b feature-payment-v2");
  await ctx.fs.edit("src/config.ts", "MODE = 'dev'", "MODE = 'production'");

  // ── LAYER 4: Lightweight Kitesurf Browser ──────────────────────────────────
  // Scrapes latest regulatory tax rates from government portal at edge
  const taxRates = await ctx.browser.kitesurf("https://revenue.state.gov/rates", [
    { type: "extract", selector: "table#current-rates" }
  ]);
  await ctx.fs.write("src/data/rates.json", JSON.stringify(taxRates));

  // ── LAYER 6: Heavy Linux Container Sandbox via gRPC ────────────────────────
  // Wakes container for 15 seconds to run native compilation & test suite
  const testRun = await ctx.container.exec("npm install && npm run test:ci", {
    timeoutMs: 30000,
    syncWorkspaceFiles: true // Ensures FUSE flushes latest rates.json before test
  });

  if (testRun.exitCode !== 0) {
    throw new Error(`Build failed in Linux container: ${testRun.stderr.slice(-500)}`);
  }

  // ── LAYER 5: Visual QA with Headless Chromium ──────────────────────────────
  // Takes high-res DOM snapshot to verify checkout button is rendered
  const qaSnapshot = await ctx.browser.chromium("https://preview.edge.app/checkout", {
    takeScreenshot: true,
    assertSelectorExists: "button#stripe-checkout-btn"
  });

  // ── LAYER 3: Dynamic Durable Workflows ─────────────────────────────────────
  // If all layers pass, register a recurring weekly audit cron
  await ctx.workflows.schedule({
    cron: "0 9 * * 1", // Every Monday at 9 AM
    workflowPath: "workflows/weekly-tax-audit.ts"
  });

  return {
    ok: true,
    gitCommit: await ctx.cli.exec("git rev-parse HEAD"),
    qaPassed: qaSnapshot.assertionPassed,
    message: "✔ Cross-layer execution completed: Code patched, native build passed, visual QA verified, and weekly cron scheduled."
  };
}
```

