// Persistent Session State inside Durable Object SQLite
export interface ShellSessionState {
  cwd: string;                      // e.g. "src/components"
  envVars: Record<string, string>;   // e.g. { NODE_ENV: "production" }
  activeGitBranch: string;          // e.g. "feature-darkmode"
}

export class NaelaoAgentDO extends DurableObject {
  private sessionState: ShellSessionState = {
    cwd: "",
    envVars: {},
    activeGitBranch: "main"
  };

  async executeCrossLayerCommand(command: string) {
    const trimmed = command.trim();

    // 1. STATEFUL COMMAND INTERCEPTION (Handled in Isolate SQLite)
    if (trimmed.startsWith("cd ")) {
      const targetDir = trimmed.replace("cd ", "").trim();
      this.sessionState.cwd = resolvePath(this.sessionState.cwd, targetDir);
      return { stdout: `✔ Changed directory to ${this.sessionState.cwd}`, exitCode: 0 };
    }

    if (trimmed.startsWith("export ")) {
      const [key, val] = trimmed.replace("export ", "").split("=");
      this.sessionState.envVars[key.trim()] = val.trim();
      return { stdout: `✔ Set environment variable ${key}=${val}`, exitCode: 0 };
    }

    // 2. VIRTUAL CLI SHIMS (Stripe, GitHub, JQ, R2 - Executed in V8 Isolate)
    if (isVirtualCliCommand(trimmed)) {
      return await executeVirtualBashShim(trimmed, this.sessionState, this.ctx);
    }

    // 3. NATIVE CONTAINER EXECUTION VIA gRPC (Tier 6 Pass-Through)
    // Synchronizes the exact session state (cwd, env, branch) into the container!
    const sandboxDO = this.env.TOOL_SANDBOX.get(this.env.TOOL_SANDBOX.idFromName(this.ctx.id.toString()));

    return await sandboxDO.fetch("http://internal/exec-grpc", {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({
        command: trimmed,
        cwd: `/workspace/${this.sessionState.cwd}`,
        envVars: this.sessionState.envVars,
        branch: this.sessionState.activeGitBranch
      })
    });
  }
}
```

