        const limit = flags["limit"] || 10;
        const storeDomain = flags["store"] || "my-store.myshopify.com";

        // Query Shopify Admin REST API securely through Outbound Worker Vault
        const res = await ctx.vault.fetchWithAuth(
          \`https://\${storeDomain}/admin/api/2026-07/products.json?limit=\${limit}\`,
          {
            credentialName: "SHOPIFY_ADMIN_TOKEN",
            method: "GET"
          }
        );

        const data = await res.json();
        const rows = data.products.map(p => ({
          ID: p.id,
          TITLE: p.title,
          STATUS: p.status,
          PRICE: p.variants[0]?.price || "N/A"
        }));

        // Returns clean terminal ASCII table to the agent
        return ctx.cli.formatTable(rows);
      }

      throw new Error(\`Subcommand '\${subcommand}' not implemented yet. Extend this CLI to add it.\`);
    }
  `
});
